/** An "active member" gate that also rejects invited/suspended rows. */
async function requireActiveMember(orgId: OrgId, userId: UserId): Promise<Member> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") {
    throw new NotFoundError("Member", userId);
  }
  return member;
}

function isAbsenceActiveAt(absence: MemberAbsence, at: IsoTimestamp): boolean {
  const moment = new Date(at).getTime();
  return (
    new Date(absence.startsAt).getTime() <= moment &&
    moment < new Date(absence.endsAt).getTime()
  );
}

/**
 * Resolves who should receive something addressed to `userId` at instant
 * `at`: `userId` itself, unless they are away with a delegate, in which case
 * the delegate — and only the delegate, never chased further even if the
 * delegate is away too.
 */
export async function resolveDelegate(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<UserId> {
  const absence = await memberRepo.findAbsence(orgId, userId);
  if (!absence || absence.delegateUserId === null) return userId;
  if (!isAbsenceActiveAt(absence, at)) return userId;
  return absence.delegateUserId;
}

/**
 * Sets or replaces `userId`'s absence. Whoever may change members' roles may
 * set or clear anyone's absence; everyone else only their own.
 */
export async function setAbsence(
  actor: Actor,
  input: SetAbsenceInput,
): Promise<MemberAbsence> {
  assertOrgScope(actor, input.orgId);

  if (new Date(input.endsAt).getTime() <= new Date(input.startsAt).getTime()) {
    throw new Error("An absence must end after it starts");
  }

  const member = await requireActiveMember(input.orgId, input.userId);

  if (actor.userId !== input.userId) {
    assertCan(actor, "member:update_role", memberResource(member));
  }

  if (input.delegateUserId !== null) {
    if (input.delegateUserId === input.userId) {
      throw new Error("A member cannot delegate to themselves");
    }
    await requireActiveMember(input.orgId, input.delegateUserId);
  }

  return memberRepo.upsertAbsence({
    orgId: input.orgId,
    userId: input.userId,
    delegateUserId: input.delegateUserId,
    startsAt: input.startsAt,
    endsAt: input.endsAt,
    note: input.note,
  });
}

/** Clearing when nothing is set is fine — it is simply a no-op delete. */
export async function clearAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  assertOrgScope(actor, orgId);

  const member = await requireActiveMember(orgId, userId);

  if (actor.userId !== userId) {
    assertCan(actor, "member:update_role", memberResource(member));
  }

  await memberRepo.deleteAbsence(orgId, userId);
}

/**
 * `null` once the absence has ended or when none is set; a scheduled absence
 * that has not started yet is still returned. Anyone in the workspace may ask.
 */
export async function getAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  assertOrgScope(actor, orgId);
  await requireActiveMember(orgId, userId);

  const absence = await memberRepo.findAbsence(orgId, userId);
  if (!absence) return null;

  const now = toIsoTimestamp(new Date());
  return new Date(absence.endsAt).getTime() > new Date(now).getTime()
    ? absence
    : null;
}

