/**
 * A mention alerts the mentioned member and, while they are away, their
 * delegate too — both get a row, but `notify()`'s own `Set` dedupes a
 * delegate who was also mentioned directly in the same comment.
 */
async function withDelegates(
  orgId: OrgId,
  userIds: readonly UserId[],
  at: IsoTimestamp,
): Promise<readonly UserId[]> {
  const expanded: UserId[] = [];
  for (const userId of userIds) {
    expanded.push(userId);
    const delegate = await memberService.resolveDelegate(orgId, userId, at);
    if (delegate !== userId) expanded.push(delegate);
  }
  return expanded;
}

